-- HEYTI: SOLO base temporal ya cargada con proyección v0.1 y extensión v0.2.
BEGIN;
DO $$ DECLARE n integer; v bigint; d bigint; published bigint; blank_count integer; BEGIN SELECT count(*) INTO n FROM electoral_stage.casilla_tally; IF n<>5 THEN RAISE EXCEPTION 'CAS piloto: % filas, esperadas 5',n; END IF; SELECT sum(ct.total_votes) INTO v FROM electoral_stage.casilla_tally ct JOIN electoral_stage.election_series es ON es.series_id=ct.series_id JOIN electoral_stage.computation_unit cu ON cu.unit_id=ct.unit_id WHERE es.election_year=2021 AND cu.section_code='218'; SELECT sum(ct.total_votes) INTO d FROM electoral_stage.casilla_tally ct JOIN electoral_stage.election_series es ON es.series_id=ct.series_id JOIN electoral_stage.computation_unit cu ON cu.unit_id=ct.unit_id WHERE es.election_year=2021 AND cu.section_code='218' AND upper(ct.tribunal)='ANULADA'; SELECT st.total_votes INTO published FROM electoral_stage.section_tally st JOIN electoral_stage.election_series es ON es.series_id=st.series_id JOIN electoral_stage.computation_unit cu ON cu.unit_id=st.unit_id WHERE es.election_year=2021 AND es.election_type='DF' AND es.modality='MR' AND cu.section_code='218'; IF v<>918 OR d<>304 OR published<>614 OR v-d<>published THEN RAISE EXCEPTION 'DF21 sección 218: CAS %, anulada %, SEC %',v,d,published; END IF; SELECT count(*) INTO blank_count FROM electoral_stage.casilla_option_vote cov JOIN electoral_stage.casilla_tally ct ON ct.casilla_id=cov.casilla_id JOIN electoral_stage.election_series es ON es.series_id=ct.series_id JOIN electoral_stage.computation_unit cu ON cu.unit_id=ct.unit_id JOIN electoral_stage.option_column oc ON oc.option_id=cov.option_id WHERE es.election_year=2018 AND cu.section_code='553' AND oc.literal_header='PAN' AND cov.votes IS NULL AND cov.raw_value='' AND cov.missing_cause='LITERAL_BLANK'; IF blank_count<>1 THEN RAISE EXCEPTION 'DF18 sección 553 PAN vacío: %',blank_count; END IF; RAISE NOTICE 'Piloto CAS v0.2 OK: 5 casillas; DF21 918-304=614; DF18 PAN vacío preservado'; END $$;
COMMIT;
