INSERT INTO electoral_stage.casilla_tally(series_id,cas_member_id,unit_id,raw_row_id,casilla_key,original_identity,total_votes,total_raw,nominal_list,nominal_raw,estatus_acta,tribunal,juicio,observaciones,ruta_acta) SELECT scm.series_id,rr.member_id,cu.unit_id,rr.raw_row_id,concat_ws('|',es.election_year,es.election_type,es.modality,rr.raw_cells->>'ID_ESTADO',rr.raw_cells->>'SECCION',rr.raw_cells->>'TIPO_CASILLA',rr.raw_cells->>'ID_CASILLA',rr.raw_cells->>'EXT_CONTIGUA',coalesce(rr.raw_cells->>'CASILLA',rr.raw_cells->>'ACTA_CASILLA-MEC','')),jsonb_build_object('ID_ESTADO',rr.raw_cells->>'ID_ESTADO','SECCION',rr.raw_cells->>'SECCION','TIPO_CASILLA',rr.raw_cells->>'TIPO_CASILLA','ID_CASILLA',rr.raw_cells->>'ID_CASILLA','EXT_CONTIGUA',rr.raw_cells->>'EXT_CONTIGUA'),nullif(rr.raw_cells->>'TOTAL_VOTOS','')::bigint,rr.raw_cells->>'TOTAL_VOTOS',nullif(rr.raw_cells->>'LISTA_NOMINAL','')::bigint,rr.raw_cells->>'LISTA_NOMINAL',rr.raw_cells->>'ESTATUS_ACTA',rr.raw_cells->>'TRIBUNAL',rr.raw_cells->>'JUICIO',rr.raw_cells->>'OBSERVACIONES',rr.raw_cells->>'RUTA_ACTA' FROM electoral_stage.raw_row rr JOIN electoral_stage.series_cas_member scm ON scm.cas_member_id=rr.member_id JOIN electoral_stage.election_series es ON es.series_id=scm.series_id JOIN electoral_stage.computation_unit cu ON cu.series_id=es.series_id AND cu.section_code=rr.raw_cells->>'SECCION' AND cu.state_code=rr.raw_cells->>'ID_ESTADO' AND cu.unit_kind='ORDINARY_SECTION';
INSERT INTO electoral_stage.casilla_option_vote(series_id,casilla_id,option_id,votes,raw_value,missing_cause) SELECT ct.series_id,ct.casilla_id,oc.option_id,nullif(rr.raw_cells->>oc.literal_header,'')::bigint,rr.raw_cells->>oc.literal_header,CASE WHEN rr.raw_cells->>oc.literal_header='' THEN 'LITERAL_BLANK' END FROM electoral_stage.casilla_tally ct JOIN electoral_stage.raw_row rr ON rr.raw_row_id=ct.raw_row_id AND rr.member_id=ct.cas_member_id JOIN electoral_stage.option_column oc ON oc.series_id=ct.series_id WHERE rr.raw_cells ? oc.literal_header;
